{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Banana_club_product_performance_factitems AS WITH base AS ( SELECT sc.marketplace AS final_marketplace, CASE WHEN UPPER(sc.marketplace) = \'WEBSITE\' THEN \'WEBSITE\' WHEN UPPER(sc.marketplace) IN (\'MYNTRAPPMP\',\'MYNTRAPPMP_EMIZA\') THEN \'MYNTRA\' WHEN UPPER(sc.marketplace) = \'MYNTRA_SJIT\' THEN \'MYNTRA_SJIT\' WHEN UPPER(sc.marketplace) LIKE \'%AJIO%\' OR UPPER(sc.marketplace) LIKE \'%FLIPKART%\' THEN \'OTHERS\' END AS marketplaces, COALESCE(sc.channel_mapped,mc.channel) channel, sc.sku, sc.Order_Date, CASE WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) THEN \'LAST 7D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'LAST 30D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) THEN \'LAST 60D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) THEN \'LAST 90D\' ELSE \'>90D\' END AS date_bucket, COALESCE(sr.QUANTITY, mr.QUANTITY, sc.QUANTITY) AS Quantity, sc.SELLING_PRICE AS Selling_price, UPPER(COALESCE(inv.name, sc.final_product_name)) AS Product_name, sc.city, COALESCE(sr.return_reason, mr.return_reason) AS Return_reason, COALESCE(sr.returned_quantity, mr.returned_quantity, sc.returned_quantity) AS returned_quantity, cc.cost, inv.inventory AS current_inventory, COALESCE(inv.image_link, sc.image_link) AS image_link, SAFE_DIVIDE(COALESCE(spend,0), COUNT(1) OVER (PARTITION BY COALESCE(sc.order_date,mc.date), COALESCE(sc.sku, mc.sku))) spend, SAFE_DIVIDE(COALESCE(IMPRESSIONS,0), COUNT(1) OVER (PARTITION BY COALESCE(sc.order_date,mc.date), COALESCE(sc.sku, mc.sku))) IMPRESSIONS, SAFE_DIVIDE(COALESCE(CLICKS,0), COUNT(1) OVER (PARTITION BY COALESCE(sc.order_date,mc.date), COALESCE(sc.sku, mc.sku))) CLICKS, SAFE_DIVIDE(COALESCE(CONVERSIONS,0), COUNT(1) OVER (PARTITION BY COALESCE(sc.order_date,mc.date), COALESCE(sc.sku, mc.sku))) CONVERSIONS, SAFE_DIVIDE(COALESCE(CONVERSION_VALUE,0), COUNT(1) OVER (PARTITION BY COALESCE(sc.order_date,mc.date), COALESCE(sc.sku, mc.sku))) CONVERSION_VALUE FROM ( SELECT *, CASE WHEN LOWER(channel) LIKE ANY (\'%facebook%\',\'%fb%\',\'%meta%\',\'%insta%\',\'%ig%\') THEN \'FACEBOOK\' WHEN LOWER(channel) LIKE ANY (\'%google%\') THEN \'GOOGLE\' ELSE UPPER(channel) END channel_mapped FROM maplemonk.bananaclub_sales_consolidated ) sc LEFT JOIN ( SELECT sku, CAST(order_timestamp AS DATE) AS Order_Date, sales_quantity AS QUANTITY, city, return_quantity AS returned_quantity, customer_reason_label AS return_reason FROM maplemonk.shopify_return_exchange QUALIFY ROW_NUMBER() OVER(PARTITION BY sku, CAST(order_timestamp AS DATE)ORDER BY order_timestamp DESC)=1 ) sr ON DATE(sc.order_date)=DATE(sr.Order_Date) AND LOWER(sc.sku) = LOWER(sr.sku) LEFT JOIN ( SELECT sku, CAST(created_on AS DATE) AS Order_Date, quantity, final_amount AS SELLING_PRICE, city, return_quantity AS returned_quantity, return_reason FROM MapleMonk.BananaClub_db_Myntra_Master QUALIFY ROW_NUMBER() OVER(PARTITION BY sku, CAST(created_on AS DATE)ORDER BY created_on DESC)=1 ) mr ON DATE(sc.order_date)=DATE(mr.Order_Date) AND LOWER(sc.sku)=LOWER(mr.sku) LEFT JOIN ( SELECT UPPER(product_name) AS product_name, MIN(CAST(cost AS INT64)) AS cost FROM ( SELECT distinct cc.sku_code, cost, sc.final_product_name AS product_name FROM maplemonk.banana_club_Google_sheet_cost cc LEFT JOIN maplemonk.bananaclub_sales_consolidated sc ON LOWER(cc.sku_code) = LOWER(sc.sku) ) GROUP BY 1) cc ON UPPER(sc.final_product_name) = cc.product_name LEFT JOIN ( SELECT i.date, i.name, i.inventory, p.image_link FROM ( SELECT FORMAT_TIMESTAMP(\'%Y-%m-%d\', _airbyte_normalized_at) AS date, name, SUM(inventory) AS inventory FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY skucode, facility ORDER BY _airbyte_normalized_at DESC ) rw FROM MAPLEMONK.Unicommerce_Unicommerce_get_inventory_snapshot ) WHERE rw = 1 GROUP BY 1,2 ) i LEFT JOIN ( SELECT name, ANY_VALUE(image_url) AS image_link FROM maplemonk.banana_club_unicommerce_get_product_master WHERE image_url IS NOT NULL GROUP BY name ) p ON UPPER(i.name) = UPPER(p.name) WHERE DATE(date) = DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) inv ON UPPER(sc.final_product_name)=UPPER(inv.name) FULL OUTER JOIN ( select Channel ,ACCOUNT ,SKU ,DATE ,SUM(CLICKS) AS CLICKS ,SUM(SPEND) AS SPEND ,SUM(IMPRESSIONS) AS IMPRESSIONS ,SUM(CONVERSIONS) AS CONVERSIONS ,SUM(CONVERSION_VALUE) AS CONVERSION_VALUE from MAPLEMONK.BANANA_CLUB_PRODUCT_MARKETING_CONSOLIDATED GROUP BY 1,2,3,4 ) mc ON DATE(sc.order_Date)=DATE(mc.date) AND UPPER(SC.SKU) = UPPER(MC.SKU) ) ,city_sales AS ( SELECT Product_name, city, SUM(quantity) total_qty FROM base GROUP BY 1,2), highest_city AS ( SELECT Product_name, city AS highest_sale_city, total_qty FROM city_sales QUALIFY ROW_NUMBER() OVER(PARTITION BY Product_name ORDER BY total_qty DESC)=1) , retail_data AS ( WITH sales AS ( SELECT JSON_VALUE(_airbyte_data, \'$.ITEM_CODE\') AS ITEM_CODE, DATE(JSON_VALUE(_airbyte_data, \'$.BILL_DATE\')) AS BILL_DATE, SUM(CAST(JSON_VALUE(_airbyte_data, \'$.SALE_QTY\') AS INT64)) AS sale_qty FROM `MAPLEMONK._airbyte_raw_logic_BQ_Salesdata_logicMM` GROUP BY 1,2 ), inventory AS ( SELECT ITEM_CODE, DATE(PURCHASE_DATE) PURCHASE_DATE, SUM(CAST(CLOSING_STOCK AS INT64)) CLOSING_STOCK FROM `MAPLEMONK.logic_BQ_Stockdata` GROUP BY 1,2 ) SELECT COALESCE(s.BILL_DATE,i.PURCHASE_DATE) AS order_date, COALESCE(s.ITEM_CODE,i.ITEM_CODE) AS sku, s.SALE_QTY, i.CLOSING_STOCK FROM sales s FULL OUTER JOIN inventory i ON UPPER(s.ITEM_CODE) = UPPER(i.ITEM_CODE) AND s.BILL_DATE = i.PURCHASE_DATE ) SELECT b.*, hc.highest_sale_city, rd.sale_qty AS retail_sales_qty, rd.closing_stock AS retail_current_inventory FROM base b LEFT JOIN highest_city hc ON LOWER(b.Product_name)=LOWER(hc.Product_name) LEFT JOIN retail_data rd ON LOWER(b.sku)=LOWER(rd.sku) AND DATE(b.order_date)=DATE(rd.order_date);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            